import os
for p,ds,fs in os.walk('studies'):
 for f in fs: print(os.path.join(p,f),os.path.getsize(os.path.join(p,f)))

import glob,gzip
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for line in h:
   if any(s in line.lower() for s in ['processing','normaliz','!sample_title','!series_summary','!sample_supplementary_file']):print(line[:18000].strip())
   if line.startswith('!series_matrix_table_begin'):
    for i in range(4):print(next(h).strip()[:700])
    break

import glob,gzip,csv,io,pandas as pd,numpy as np,tarfile
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 txt=gzip.open(f,'rt').read()
 for line in txt.splitlines():
  if any(s in line.lower() for s in ['processing','!sample_description']):print(line.split('\t')[0],set(next(csv.reader([line],delimiter='\t'))[1:]))
 body=txt.split('!series_matrix_table_begin\n')[-1].split('!series_matrix_table_end')[0]
 if len(body.strip())>0:
  df=pd.read_csv(io.StringIO(body),sep='\t',index_col=0)
  print(df.shape,df.iloc[:3,:3]); a=df.to_numpy(dtype=float);print('quantiles',np.nanquantile(a,[0,.01,.5,.99,1]))
